function certificateId(username, code){var input=(username+"|"+code).toUpperCase(),hash=0;for(var i=0;i<input.length;i++)hash=((hash<<5)-hash)+input.charCodeAt(i)|0;return "EDU-"+Math.abs(hash).toString(36).toUpperCase().padStart(7,"0");}
function esc(v){return String(v||"").replace(/[&<>\"]/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c];});}
function certContext(){var session=requireLogin("student");if(!session)return null;var profile=findStudentByUsername(session.username);return profile?{session:session,profile:profile}:null;}
function renderCertificates(){var x=certContext(),box=document.getElementById("certificates-container");if(!x||!box)return;var codes=getEnrolledCourseCodes(x.session.username),courses=getAllCourses(),html="";for(var i=0;i<codes.length;i++)for(var j=0;j<courses.length;j++)if(courses[j].code.toLowerCase()===codes[i].toLowerCase()&&isCourseCompleted(x.session.username,courses[j].code)){var info=getCourseProgress(x.session.username,courses[j].code),id=certificateId(x.session.username,courses[j].code);html+='<div class="panel" style="margin-bottom:16px;"><div class="panel-head"><div><h3>'+esc(courses[j].name)+'</h3><p style="margin:0;color:var(--muted-dim);">'+esc(courses[j].code)+' · Certificate '+id+'</p></div><span class="pill active">Completed</span></div><p>Completed on '+new Date(info.completedAt).toLocaleDateString()+'.</p><a class="btn btn-primary btn-sm" href="/certificate?course='+encodeURIComponent(courses[j].code)+'"><i class="fa-solid fa-certificate"></i> View Certificate</a></div>';}box.innerHTML=html||'<div class="placeholder-box">No certificates yet. Complete an enrolled course to unlock your certificate.</div>';}
function renderCertificate(){var x=certContext(),area=document.getElementById("certificate-area");if(!x||!area)return;var code=new URLSearchParams(window.location.search).get("course")||"",course=findCourseByCode(code);if(!course||!isEnrolled(x.session.username,course.code)||!isCourseCompleted(x.session.username,course.code)){area.innerHTML='<div class="status-card"><div class="status-icon pending"><i class="fa-solid fa-lock"></i></div><h2>Certificate unavailable</h2><p>Complete the enrolled course before opening its certificate.</p><div class="status-actions"><a class="btn btn-primary btn-block" href="/courses">Browse Courses</a><a class="btn btn-ghost btn-block" href="/certificates">Back to Certificates</a></div></div>';return;}var info=getCourseProgress(x.session.username,course.code),done=new Date(info.completedAt),id=certificateId(x.session.username,course.code);var html='<!doctype html><html><head><meta charset="utf-8"><title>EduLedger Certificate - '+esc(course.name)+'</title><style>body{font-family:Georgia,serif;background:#f3efe6;padding:40px}.cert{max-width:900px;margin:auto;background:#fffdf7;border:12px double #b89b5e;padding:60px;text-align:center}.brand{letter-spacing:4px;color:#8c6b2f}.title{font-size:48px;color:#3f3324}.name{font-size:38px;color:#8c6b2f}.course{font-size:28px;font-weight:bold}.meta{margin-top:40px;line-height:1.8}.id{margin-top:35px;font-size:12px;color:#777}</style></head><body><div class="cert"><div class="brand">EDULEDGER · STUDENT COURSE MANAGEMENT</div><div class="title">Certificate of Completion</div><p>This certificate is proudly presented to</p><div class="name">'+esc(x.profile.name)+'</div><p>for successfully completing</p><div class="course">'+esc(course.name)+' ('+esc(course.code)+')</div><div class="meta">Instructor: '+esc(course.instructor)+'<br>Student ID: '+esc(x.profile.studentId)+'<br>Completed: '+esc(done.toLocaleDateString())+'</div><div class="id">Certificate ID: '+id+'</div></div></body></html>';area.innerHTML='<div class="certificate-preview"><div class="certificate-brand">EDULEDGER · STUDENT COURSE MANAGEMENT</div><h2>Certificate of Completion</h2><p>This certificate is proudly presented to</p><div class="certificate-name">'+esc(x.profile.name)+'</div><p>for successfully completing</p><div class="certificate-course">'+esc(course.name)+' ('+esc(course.code)+')</div><div class="certificate-meta">Instructor: '+esc(course.instructor)+'<br/>Student ID: '+esc(x.profile.studentId)+'<br/>Completed: '+esc(done.toLocaleDateString())+'</div><div class="certificate-id">Certificate ID: '+id+'</div></div><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin-top:18px"><button id="download-certificate" class="btn btn-primary"><i class="fa-solid fa-download"></i> Download Certificate</button><button id="print-certificate" class="btn btn-ghost"><i class="fa-solid fa-print"></i> Print / Save as PDF</button></div>';document.getElementById("download-certificate").onclick=function(){var blob=new Blob([html],{type:"text/html"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="EduLedger-Certificate-"+course.code+".html";a.click();setTimeout(function(){URL.revokeObjectURL(url)},500)};document.getElementById("print-certificate").onclick=function(){window.print()};}
document.addEventListener("DOMContentLoaded",function(){if(document.getElementById("certificates-container"))renderCertificates();if(document.getElementById("certificate-area"))renderCertificate();});
